head.script:
scwin.fireDbClick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 float항목의 필드에 '0'값을 입력하고 enter 또는 다른영역을 마우스로 클릭한다.
    //1. After executing the sample, enter '0' in the field of the float item and click on the enter or other area with the mouse.
    WebSquare.wUnit.addCommand("set", "scwin.fireDbClick($p.id+'grid1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grid1__column6').setValue('0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_cell_0_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 정상적으로 '0'값이 입력되어 보여진다. (이전에는 '0'값이 입력되지 않음)
    //1. Normally '0' value is displayed. (Previously no '0' value is entered)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid1_cell_0_2').innerText == '0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setRef({
        ref: "vector",
        baseNode: "vector",
        repeatNode: "data"
    });
    grid1.insertRow();
    grid1.setCellInputType(0, 0, {
        inputType: "text",
        options: {
            dataType: "float",
            displayFormat: "#,###.##"
        }
    });
    grid1.setCellData(0, 1, "float");
    grid1.insertRow();
    grid1.setCellInputType(1, 0, {
        inputType: "text",
        options: {
            dataType: "number",
            displayFormat: "#,###.##"
        }
    });
    grid1.setCellData(1, 1, "number");
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest	
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
